package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.Comparator;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AutoClosePeriods {
    // Once the sheet's today is changed: with grace days set, every open period whose to-date plus the grace days is before the
    // new today is closed as a close by hand would (its people's figures fixed as they stand now), in order of their to-dates,
    // each audited as PERIOD_CLOSED ending auto=yes. A soft-closed period keeps the figures it was fixed at.
    public void autoClose(@Val Sheet sheet, Periods periods, Rollup rollup, Settings settings,
            ServerHttpConnection connection, Audit audit) {
        String sheetId = sheet.id();
        Integer grace = settings.graceDays(sheetId);
        if (grace == null) {
            return;
        }
        LocalDate today = sheet.today();
        for (Period period : periods.list(sheetId).stream().sorted(Comparator.comparing(Period::to)).toList()) {
            if (period.closed() || period.soft() || !period.to().plusDays(grace).isBefore(today)) {
                continue;
            }
            Period closed = period.closedAt(rollup.personDueTotals(sheetId, period.from(), period.to()));
            if (periods.close(closed)) {
                audit.record(Audit.line("PERIOD_CLOSED", sheetId, Audit.user(connection), "period=" + closed.name(),
                        "total=" + closed.closedTotal().toPlainString(), "auto=yes"));
            }
        }
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import net.officefloor.server.http.HttpHeader;
import net.officefloor.server.http.ServerHttpConnection;
import java.util.Set;
import net.officefloor.hq.app.setting.Settings;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The lines that only report figures: they never name the steward a change is made for. */
    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");

    private final Path file;
    private final ObjectProvider<Settings> settings;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<Settings> settings) {
        this.file = Path.of(path);
        this.settings = settings;
    }

    /**
     * Append one audit record. Tests assert the exact line(s) in the file. A change made by a user the steward role is
     * delegated to (for the sheet's today) ends with for=<the steward who delegated>, unless the line only reports figures.
     */
    public synchronized void record(String entry) {
        String delegator = delegator(entry);
        if (delegator != null) {
            entry = entry + " for=" + delegator;
        }
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** The steward who delegated to the user the line is by, on the line's sheet; null when none did or the line only reports figures. */
    private String delegator(String entry) {
        String[] parts = entry.split(" ", 4);
        if (parts.length < 3 || FIGURES.contains(parts[0]) || !parts[1].startsWith("sheet=") || !parts[2].startsWith("by=")) {
            return null;
        }
        return settings.getObject().delegator(parts[1].substring("sheet=".length()), parts[2].substring("by=".length()));
    }

    /** The signed-in user a write names in its X-User header ("" when it names none). */
    public static String user(ServerHttpConnection connection) {
        HttpHeader header = connection.getRequest().getHeaders().getHeader("X-User");
        return header == null ? "" : header.getValue();
    }

    /** One record: the event, then sheet=<id> and by=<user>, then the fields, separated by single spaces. */
    public static String line(String event, String sheetId, String user, String... fields) {
        StringBuilder line = new StringBuilder(event).append(" sheet=").append(sheetId)
                .append(" by=").append(user == null ? "" : user.trim());
        for (String field : fields) {
            line.append(' ').append(field);
        }
        return line.toString();
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.Audit;

/** The ROLLUP and TOTALS lines a change records, shared by the steps that record them. */
public final class RollupLines {

    private RollupLines() {
    }

    /** Record the lines for what moved since {@code before}; the sheet's figures now, for a later comparison. */
    public static Figures record(String sheet, String user, Figures before, Rollup rollup, Audit audit) {
        Figures after = rollup.figures(sheet);
        after.people().forEach((id, now) -> {
            if (!now.sameAs(before.people().get(id))) {
                audit.record(Audit.line("ROLLUP", sheet, user, "person=" + now.name(), "claimed=" + now.claimed(),
                        "due-total=" + now.dueTotal(), "overdue-total=" + now.overdueTotal()));
            }
        });
        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())
                || !after.overdueTotal().equals(before.overdueTotal())) {
            audit.record(Audit.line("TOTALS", sheet, user, "claimed-total=" + after.claimedTotal(),
                    "due-total=" + after.dueTotal(), "overdue-total=" + after.overdueTotal()));
        }
        return after;
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class AuditRollup {
    // After the change's own lines: one ROLLUP per person whose figures moved (a new person counts as moved),
    // in the order they were added, then TOTALS when a sheet total moved.
    public void audit(@PathVariable("sheetId") String sheetId, @Val Figures before, Rollup rollup,
            ServerHttpConnection connection, Audit audit) {
        RollupLines.record(sheetId.trim(), Audit.user(connection), before, rollup, audit);
    }
}

